mapper.select:
SELECT * FROM EQUITY_CHANGE_RECORD
WHERE EQUITY_ID = #{equityId}
ORDER BY CHANGE_DATE DESC

SELECT * FROM EQUITY_CHANGE_RECORD
WHERE INVESTEE_ENTERPRISE_ID = #{investeeEnterpriseId}
ORDER BY CHANGE_DATE DESC

SELECT * FROM EQUITY_CHANGE_RECORD
WHERE INVESTOR_ENTERPRISE_ID = #{investorEnterpriseId}
ORDER BY CHANGE_DATE DESC

SELECT * FROM EQUITY_CHANGE_RECORD
WHERE IS_MAJOR_CHANGE = #{isMajorChange}
ORDER BY CHANGE_DATE DESC

SELECT * FROM EQUITY_CHANGE_RECORD
WHERE NEED_WARNING = #{needWarning}
ORDER BY WARNING_LEVEL DESC, CHANGE_DATE DESC

SELECT * FROM EQUITY_CHANGE_RECORD
WHERE CHANGE_TYPE = #{changeType}
ORDER BY CHANGE_DATE DESC

SELECT * FROM EQUITY_CHANGE_RECORD
WHERE APPROVAL_STATUS = #{approvalStatus}
ORDER BY CHANGE_DATE DESC

SELECT * FROM EQUITY_CHANGE_RECORD
WHERE WARNING_LEVEL = #{warningLevel}
ORDER BY CHANGE_DATE DESC

SELECT * FROM EQUITY_CHANGE_RECORD
WHERE INVESTEE_ENTERPRISE_ID = #{investeeEnterpriseId}
ORDER BY CHANGE_DATE DESC

    LIMIT #{limit}


    AND ROWNUM <= #{limit}

SELECT CHANGE_TYPE as changeType, COUNT(*) as count, SUM(CHANGE_AMOUNT) as totalAmount, AVG(CHANGE_AMOUNT) as avgAmount FROM EQUITY_CHANGE_RECORD WHERE 1=1
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY CHANGE_TYPE ORDER BY count DESC

SELECT CHANGE_REASON as changeReason, COUNT(*) as count, SUM(CHANGE_AMOUNT) as totalAmount, AVG(CHANGE_AMOUNT) as avgAmount FROM EQUITY_CHANGE_RECORD WHERE 1=1
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY CHANGE_REASON ORDER BY count DESC

SELECT 
    APPROVAL_STATUS as approvalStatus,
    COUNT(*) as count,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM EQUITY_CHANGE_RECORD 
        WHERE 1=1

            AND CHANGE_DATE >= #{startDate}


            AND CHANGE_DATE <= #{endDate}

    ), 2) as percentage
FROM EQUITY_CHANGE_RECORD
WHERE 1=1

    AND CHANGE_DATE >= #{startDate}


    AND CHANGE_DATE <= #{endDate}

GROUP BY APPROVAL_STATUS
ORDER BY count DESC

SELECT WARNING_LEVEL as warningLevel, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM EQUITY_CHANGE_RECORD WHERE NEED_WARNING = 1
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
), 2) as percentage FROM EQUITY_CHANGE_RECORD WHERE NEED_WARNING = 1
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY WARNING_LEVEL ORDER BY CASE WARNING_LEVEL WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 ELSE 5 END

mapper.delete:
DELETE FROM EQUITY_CHANGE_RECORD WHERE APPROVAL_STATUS = 'CANCELLED' AND UPDATE_TIME <
DATE_SUB(NOW(), INTERVAL #{days} DAY)
SYSDATE - #{days}
